-- Ghi yêu cầu xóa cùng transaction nghiệp vụ; API được gọi sau khi commit.
BEGIN;
CREATE TABLE IF NOT EXISTS public."sys_PendingFileDeletion" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RelativePath" varchar(1000) NOT NULL,
    "CreatedAt" timestamp NOT NULL,
    "NextAttemptAt" timestamp NOT NULL,
    "AttemptCount" integer NOT NULL DEFAULT 0,
    "LastError" varchar(1000)
);
CREATE INDEX IF NOT EXISTS "IX_PendingFileDeletion_NextAttempt"
    ON public."sys_PendingFileDeletion" ("NextAttemptAt");
COMMIT;
